import{_ as a,o as s,c as n,aO as t}from"./chunks/framework.vjUPZZJn.js";const u=JSON.parse('{"title":"GitHub SSH 走代理与 443 端口配置","description":"","frontmatter":{"date":"2026-09-22T20:00:00.000Z","title":"GitHub SSH 走代理与 443 端口配置","source":[["1-知识/工具/网络代理与远程/GitHub SSH代理配置"]],"tags":["工具","教程手册","git","SSH"],"categories":["工具"],"permalink":"/pages/58b286"},"headers":[],"relativePath":"工具/GitHub SSH 走代理与 443 端口配置.md","filePath":"工具/GitHub SSH 走代理与 443 端口配置.md","lastUpdated":1790043993000}'),o={name:"工具/GitHub SSH 走代理与 443 端口配置.md"};function i(c,e,d,r,p,l){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="github-ssh-走代理与-443-端口配置" tabindex="-1">GitHub SSH 走代理与 443 端口配置 <a class="header-anchor" href="#github-ssh-走代理与-443-端口配置" aria-label="Permalink to &quot;GitHub SSH 走代理与 443 端口配置&quot;">​</a></h1> <p><code>git clone</code> 走 HTTPS 时通常能自动继承系统代理，但换成 SSH 协议后常常超时。原因有两个：SSH 不识别 <code>http_proxy</code>/<code>https_proxy</code> 环境变量，默认直连目标主机；而 GitHub SSH 的标准入口 22 端口又可能被网络封锁或限制。本文给出一段 <code>~/.ssh/config</code> 配置，同时解决这两个问题：用 <code>ProxyCommand</code> 把 SSH 流量交给本地代理转发，并改走 GitHub 官方提供的 443 端口 SSH 入口。适用于在受限网络环境下通过 SSH 协议访问 GitHub 的开发者。</p> <h2 id="原理" tabindex="-1">原理 <a class="header-anchor" href="#原理" aria-label="Permalink to &quot;原理&quot;">​</a></h2> <p>两个独立的问题，各对应一个手段：</p> <table tabindex="0"><thead><tr><th>问题</th> <th>手段</th></tr></thead> <tbody><tr><td>SSH 不走系统代理</td> <td><code>ProxyCommand</code> 指定代理命令，由它代替 SSH 建立到目标的 TCP 连接</td></tr> <tr><td>22 端口被封或被限</td> <td>改连 <code>ssh.github.com:443</code>，GitHub 官方提供的 HTTPS 端口 SSH 入口</td></tr></tbody></table> <p><code>ssh.github.com:443</code> 是 <a href="https://docs.github.com/en/authentication/troubleshooting-ssh/using-ssh-over-the-https-port" target="_blank" rel="noreferrer">GitHub 官方文档</a>明确支持的连接方式，功能与标准 22 端口入口相同。注意两点限制：GitHub Enterprise Server 不支持此方式；首次连接 443 入口时会出现新的主机指纹确认提示，与 <a href="https://docs.github.com/en/authentication/keeping-your-account-and-data-secure/githubs-ssh-key-fingerprints" target="_blank" rel="noreferrer">GitHub 官方公布指纹</a>比对一致后确认即可。</p> <h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2> <h3 id="linux-macos-nc-版" tabindex="-1">Linux / macOS（nc 版） <a class="header-anchor" href="#linux-macos-nc-版" aria-label="Permalink to &quot;Linux / macOS（nc 版）&quot;">​</a></h3> <p>编辑 <code>~/.ssh/config</code>：</p> <div class="language-ssh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ssh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host github.com</span></span>
<span class="line"><span>    Hostname ssh.github.com</span></span>
<span class="line"><span>    Port 443</span></span>
<span class="line"><span>    User git</span></span>
<span class="line"><span>    # 假设代理端口为 7890，根据实际情况修改</span></span>
<span class="line"><span>    ProxyCommand nc -X 5 -x 127.0.0.1:7890 %h %p</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>逐行说明：</p> <ul><li><code>Host github.com</code>：对目标为 <code>github.com</code> 的 SSH 连接生效。使用 <code>git@github.com:user/repo.git</code> 地址的仓库无需改动远程地址。</li> <li><code>Hostname ssh.github.com</code> + <code>Port 443</code>：实际连接指向 GitHub 的 443 端口 SSH 入口。</li> <li><code>ProxyCommand</code>：建立连接前先执行该命令，由命令负责与目标建立 TCP 通道；<code>%h</code>、<code>%p</code> 分别展开为目标主机和端口。</li> <li><code>nc -X 5 -x 127.0.0.1:7890</code>：<code>-X 5</code> 指定 SOCKS5 协议，<code>-x</code> 指定代理地址，按本地代理实际端口修改。</li></ul> <p><code>-X</code>/<code>-x</code> 是 OpenBSD netcat 的选项。多数发行版的 <code>/usr/bin/nc</code> 已指向 openbsd-netcat；如果环境里只有 Nmap 的 ncat，等价写法是 <code>ProxyCommand ncat --proxy 127.0.0.1:7890 --proxy-type socks5 %h %p</code>。</p> <h3 id="windows-git-bash-connect-版" tabindex="-1">Windows（Git Bash，connect 版） <a class="header-anchor" href="#windows-git-bash-connect-版" aria-label="Permalink to &quot;Windows（Git Bash，connect 版）&quot;">​</a></h3> <p>Git for Windows 自带 <a href="https://github.com/gotoh/ssh-connect" target="_blank" rel="noreferrer">connect</a> 代理工具（位于 <code>mingw64/bin</code>，Git Bash 内可直接调用），无需额外安装：</p> <div class="language-ssh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ssh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Host github.com</span></span>
<span class="line"><span>    Hostname ssh.github.com</span></span>
<span class="line"><span>    Port 443</span></span>
<span class="line"><span>    User git</span></span>
<span class="line"><span>    ProxyCommand connect -S 127.0.0.1:7890 %h %p</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p><code>-S</code> 指定 SOCKS 代理；本地代理是 HTTP 类型时改用 <code>-H</code>。</p> <h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -T</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git@github.com</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>认证成功时 GitHub 返回 <code>Hi &lt;username&gt;! You&#39;ve successfully authenticated...</code>，同时提示不提供 shell 访问，属正常输出。至此 <code>git clone</code>、<code>git push</code> 等 SSH 协议操作都会走这条通道。</p> <h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2> <p>配置的核心是三件事：<code>ProxyCommand</code> 让 SSH 流量过本地代理，<code>ssh.github.com:443</code> 绕开 22 端口封锁，<code>Host github.com</code> 别名保证现有仓库的远程地址一行都不用改。三个部分相互独立：网络只封锁端口时，仅用 443 入口即可；SSH 直连本就不通时，仅靠代理转发也能解决。</p>`,40)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
